INSERT INTO cfg.rule (id, indicator_id, low, high, title, explanation, action, threshold_source) VALUES
  (1, 'glucose', 65.0, 99.0, 'Glucose out of range', 'Your blood glucose is outside the normal range of 65 to 99 mg/dL. This can be a sign of abnormal glucose regulation.', 'Ask for a metabolic assessment.', 'Normal range given for glucose in the Inspiration4 metabolic panel file (NASA OSDR, OSD-575).'),
  (2, 'resting_heart_rate', NULL, 100.0, 'Resting heart rate high', 'Your resting heart rate is above 100 bpm. At rest, this can point to dehydration, infection, stress or a cardiovascular problem.', 'Check your hydration and how you feel, and ask for a cardiovascular assessment.', 'American Heart Association definition of tachycardia: a resting heart rate above 100 bpm. General adult reference on Earth, not a spaceflight limit.'),
  (3, 'sleep_duration', 420.0, NULL, 'Short night', 'You slept less than 7 hours (420 minutes). Too little sleep, night after night, lowers attention and mood.', 'Adjust your schedule to protect tonight''s sleep and review what kept you awake.', 'American Academy of Sleep Medicine and Sleep Research Society consensus for adults, 2015: 7 or more hours per night. https://doi.org/10.5664/jcsm.4758. General adult reference on Earth, not a spaceflight limit.'),
  (4, 'mood_sad_days_14', NULL, 7.0, 'Sad on most of the last 14 days', 'You chose Sad on more than half of the last 14 days. It is not a diagnosis. It is a reason to talk about it.', 'Bring it up in your next private psychological conference.', 'PHQ-2 depression screening (Kroenke, Spitzer and Williams, Medical Care, 2003) asks about the last 2 weeks, and "more than half the days" is the answer that starts to count. This is an adaptation, not a validated screening: each questionnaire has two questions and the check-in covers one. To confirm with the medical reviewer.'),
  (5, 'mood_tense_days_14', NULL, 7.0, 'Tense or anxious on most of the last 14 days', 'You chose Tense or anxious on more than half of the last 14 days. It is not a diagnosis. It is a reason to talk about it.', 'Bring it up in your next private psychological conference.', 'GAD-2 anxiety screening (Kroenke et al., Annals of Internal Medicine, 2007) asks about the last 2 weeks, and "more than half the days" is the answer that starts to count. This is an adaptation, not a validated screening: each questionnaire has two questions and the check-in covers one. To confirm with the medical reviewer.'),
  (6, 'sodium', 135.0, 146.0, 'Sodium out of range', 'Your blood sodium is outside the normal range of 135 to 146 mmol/L. This is an electrolyte imbalance.', 'Repeat the test and ask for a clinical review.', 'Normal range given for sodium in the Inspiration4 metabolic panel file (NASA OSDR, OSD-575).'),
  (7, 'potassium', 3.5, 5.3, 'Potassium out of range', 'Your blood potassium is outside the normal range of 3.5 to 5.3 mmol/L. This is an electrolyte imbalance.', 'Repeat the test and ask for a clinical review.', 'Normal range given for potassium in the Inspiration4 metabolic panel file (NASA OSDR, OSD-575).'),
  (8, 'chloride', 98.0, 110.0, 'Chloride out of range', 'Your blood chloride is outside the normal range of 98 to 110 mmol/L. This is an electrolyte imbalance.', 'Repeat the test and ask for a clinical review.', 'Normal range given for chloride in the Inspiration4 metabolic panel file (NASA OSDR, OSD-575).'),
  (9, 'urea_nitrogen', 7.0, 25.0, 'Urea nitrogen out of range', 'Your blood urea nitrogen is outside the normal range of 7 to 25 mg/dL. This can be a sign of a change in kidney function.', 'Ask for a renal assessment.', 'Normal range given for urea nitrogen (BUN) in the Inspiration4 metabolic panel file (NASA OSDR, OSD-575).'),
  (10, 'egfr', 60.0, NULL, 'Kidney filtration rate low', 'Your estimated kidney filtration rate (eGFR) is below 60 mL/min/1.73 m². This can be a sign that the kidneys are working less well.', 'Ask for a renal assessment.', 'Lower limit given for eGFR in the Inspiration4 metabolic panel file (NASA OSDR, OSD-575). The file gives no upper limit.'),
  (11, 'albumin', 3.6, 5.1, 'Albumin out of range', 'Your blood albumin is outside the normal range of 3.6 to 5.1 g/dL. This can be a sign of a nutritional deficiency.', 'Ask for a targeted nutritional assessment.', 'Normal range given for albumin in the Inspiration4 metabolic panel file (NASA OSDR, OSD-575).'),
  (12, 'creatinine', 0.5, 1.35, 'Creatinine out of range', 'Your creatinine is outside the normal range of 0.5 to 1.35 mg/dL. This can be a sign of a change in kidney function.', 'Ask for a renal assessment.', 'Widest of the normal ranges given for creatinine in the Inspiration4 metabolic panel file (NASA OSDR, OSD-575). The file gives a different range by astronaut and draw.'),
  (13, 'calcium', 8.6, 10.4, 'Calcium out of range', 'Your blood calcium is outside the normal range of 8.6 to 10.4 mg/dL.', 'Repeat the test and ask for a clinical review.', 'Widest of the normal ranges given for calcium in the Inspiration4 metabolic panel file (NASA OSDR, OSD-575). The file gives a different range by astronaut and draw.');
